sql_query:
SELECT "PubMed ID"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("PubMed ID", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "PubMed ID" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("PubMed ID", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_pubmed_url(source_value) AS "pubmed_url"
FROM base;
